<?php $page='budget';$title='Budget';require_once __DIR__.'/includes/functions.php';require_login();$uid=$_SESSION['user_id'];verify_csrf();if($_SERVER['REQUEST_METHOD']==='POST'){$amount=(float)($_POST['amount']??0);$period=$_POST['period']??'monthly';$start=$_POST['start_date']??date('Y-m-01');if($amount>0&&in_array($period,['weekly','monthly'],true)){$q=$pdo->prepare('INSERT INTO budgets(user_id,amount,period,start_date) VALUES(?,?,?,?)');$q->execute([$uid,$amount,$period,$start]);set_flash('Budget saved successfully.');}else set_flash('Please enter a valid budget amount.','error');header('Location: budget.php');exit;}
$q=$pdo->prepare('SELECT * FROM budgets WHERE user_id=? ORDER BY start_date DESC,id DESC LIMIT 1');$q->execute([$uid]);$budgetRow=$q->fetch();$amount=(float)($budgetRow['amount']??0);$period=$budgetRow['period']??'monthly';$start=$period==='weekly'?date('Y-m-d',strtotime('monday this week')):date('Y-m-01');$end=$period==='weekly'?date('Y-m-d',strtotime('sunday this week')):date('Y-m-t');$tot=get_totals($pdo,$uid,$start,$end);$spent=$tot['expense'];$remaining=$amount-$spent;$cats=$pdo->prepare("SELECT category,SUM(amount) total FROM transactions WHERE user_id=? AND type='expense' AND transaction_date BETWEEN ? AND ? GROUP BY category ORDER BY total DESC");$cats->execute([$uid,$start,$end]);require 'includes/header.php';?>
<div class="page-head"><div><h1>Budget Management</h1><p>Set monthly or weekly budget and monitor spending.</p></div><a class="btn" href="#set-budget">＋ Set Budget</a></div><div class="card"><h3>Current <?=e(ucfirst($period))?> Budget</h3><div class="stat-value"><?=money($amount)?></div><div class="progress" style="margin:20px 0 12px"><span style="width:<?=$amount>0?min(100,($spent/$amount)*100):0?>%"></span></div><?=money($spent)?> spent • <?=money($remaining)?> remaining <p class="muted">Period: <?=e($start)?> to <?=e($end)?></p></div><div class="grid"><?php foreach(['Food','Transportation','School','Personal Needs','Entertainment','Others'] as $c):?><div class="card"><div class="stat-label"><?=e($c)?></div><div class="stat-value"><?php $q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) FROM transactions WHERE user_id=? AND type='expense' AND category=? AND transaction_date BETWEEN ? AND ?");$q->execute([$uid,$c,$start,$end]);echo money($q->fetchColumn());?></div></div><?php endforeach;?></div><div class="card form-card" id="set-budget"><h3>Set a New Budget</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Budget Amount (₱)</label><input type="number" name="amount" min="0.01" step="0.01" required></div><div class="field"><label>Budget Period</label><select name="period"><option value="monthly">Monthly</option><option value="weekly">Weekly</option></select></div><div class="field"><label>Start Date</label><input type="date" name="start_date" value="<?=date('Y-m-01')?>" required></div><button class="btn">Save Budget</button></form></div><?php require 'includes/footer.php';?>
